[CmdletBinding()]
param([string]$ProjectRoot=(Get-Location).Path,[Parameter(Mandatory)][string]$Context,[int]$Top=5)
$ErrorActionPreference='Stop';$project=(Resolve-Path -LiteralPath $ProjectRoot).Path;$profilePath=Join-Path $project 'herdr\dispatch-profile.json';$profile=if(Test-Path $profilePath){Get-Content $profilePath -Raw|ConvertFrom-Json}else{$null};$cfg=$profile.knowledge_retrieval;if(-not $cfg -or -not $cfg.enabled){[ordered]@{status='disabled'}|ConvertTo-Json -Compress;exit 0};$indexPath=Join-Path $project '.knowledge\index\semantic-index.json';if(-not(Test-Path $indexPath)){[ordered]@{status='unavailable';reason='semantic_index_missing';build_command='Build-KnowledgeIndex.ps1'}|ConvertTo-Json -Compress;exit 0};$index=Get-Content $indexPath -Raw|ConvertFrom-Json;function Embed([string]$Text){$body=@{model=$index.model;input=$Text}|ConvertTo-Json -Compress;$r=Invoke-RestMethod -Uri "$($index.endpoint)/api/embed" -Method Post -ContentType 'application/json' -Body $body -TimeoutSec 30;$v=@($r.embeddings[0]);if(-not $v.Count){throw 'embedding response has no vector'};return $v};function Cos($a,$b){$dot=0.0;$aa=0.0;$bb=0.0;for($i=0;$i -lt $a.Count;$i++){$dot+=[double]$a[$i]*[double]$b[$i];$aa+=[double]$a[$i]*[double]$a[$i];$bb+=[double]$b[$i]*[double]$b[$i]};if($aa -eq 0 -or $bb -eq 0){return 0};return $dot/[math]::Sqrt($aa*$bb)};try{$q=Embed $Context;$hits=@($index.entries|ForEach-Object{[ordered]@{knowledge_id=$_.id;source=$_.source;score=[math]::Round((Cos $q @($_.embedding)),4)}}|Sort-Object score -Descending|Select-Object -First $Top);[ordered]@{status='ready';model=$index.model;hits=$hits}|ConvertTo-Json -Depth 5}catch{[ordered]@{status='unavailable';reason=$_.Exception.Message}|ConvertTo-Json -Compress}
